export interface PhoneValidationResult {
  isValid: boolean;
  isMobile: boolean;
  formattedNumber: string; // E.164 e.g. +61412345678
  displayNumber: string;   // Display format e.g. +61 412 345 678
  errorReason?: string;
}

export function validatePhone(countryCode: string, rawNumber: string): PhoneValidationResult {
  const cleanCode = countryCode.trim().startsWith('+') ? countryCode.trim() : `+${countryCode.trim()}`;
  let digits = rawNumber.replace(/\D/g, '');

  // Strip leading 0 if present (e.g. 0412345678 -> 412345678)
  if (digits.startsWith('0')) {
    digits = digits.substring(1);
  }

  if (!digits) {
    return {
      isValid: false,
      isMobile: false,
      formattedNumber: '',
      displayNumber: '',
      errorReason: 'Mobile phone number is required.',
    };
  }

  switch (cleanCode) {
    case '+61': { // Australia
      const isMobile = digits.startsWith('4');
      const isLandline = ['2', '3', '7', '8'].includes(digits.charAt(0));
      const isValidLength = digits.length === 9;

      if (isLandline) {
        return {
          isValid: false,
          isMobile: false,
          formattedNumber: `${cleanCode}${digits}`,
          displayNumber: `${cleanCode} ${digits}`,
          errorReason: 'Please enter an Australian mobile number (starting with 04) rather than a landline.',
        };
      }
      if (!isMobile) {
        return {
          isValid: false,
          isMobile: false,
          formattedNumber: `${cleanCode}${digits}`,
          displayNumber: `${cleanCode} ${digits}`,
          errorReason: 'Australian mobile numbers must start with 04 (e.g. 412 345 678).',
        };
      }
      if (!isValidLength) {
        return {
          isValid: false,
          isMobile: true,
          formattedNumber: `${cleanCode}${digits}`,
          displayNumber: `${cleanCode} ${digits}`,
          errorReason: `Australian mobile numbers require 9 digits (e.g. 412 345 678). Entered ${digits.length} digits.`,
        };
      }
      return {
        isValid: true,
        isMobile: true,
        formattedNumber: `${cleanCode}${digits}`,
        displayNumber: `${cleanCode} ${digits.substring(0, 3)} ${digits.substring(3, 6)} ${digits.substring(6)}`,
      };
    }

    case '+971': { // UAE
      const isMobile = digits.startsWith('5');
      const isValidLength = digits.length === 9;

      if (!isMobile) {
        return {
          isValid: false,
          isMobile: false,
          formattedNumber: `${cleanCode}${digits}`,
          displayNumber: `${cleanCode} ${digits}`,
          errorReason: 'UAE mobile numbers must start with 05 (e.g. 50 123 4567).',
        };
      }
      if (!isValidLength) {
        return {
          isValid: false,
          isMobile: true,
          formattedNumber: `${cleanCode}${digits}`,
          displayNumber: `${cleanCode} ${digits}`,
          errorReason: `UAE mobile numbers require 9 digits (e.g. 50 123 4567). Entered ${digits.length} digits.`,
        };
      }
      return {
        isValid: true,
        isMobile: true,
        formattedNumber: `${cleanCode}${digits}`,
        displayNumber: `${cleanCode} ${digits.substring(0, 2)} ${digits.substring(2, 5)} ${digits.substring(5)}`,
      };
    }

    case '+44': { // UK
      const isMobile = digits.startsWith('7');
      const isValidLength = digits.length === 10;

      if (!isMobile) {
        return {
          isValid: false,
          isMobile: false,
          formattedNumber: `${cleanCode}${digits}`,
          displayNumber: `${cleanCode} ${digits}`,
          errorReason: 'UK mobile numbers must start with 07 (e.g. 7123 456789).',
        };
      }
      if (!isValidLength) {
        return {
          isValid: false,
          isMobile: true,
          formattedNumber: `${cleanCode}${digits}`,
          displayNumber: `${cleanCode} ${digits}`,
          errorReason: `UK mobile numbers require 10 digits (e.g. 7123 456789). Entered ${digits.length} digits.`,
        };
      }
      return {
        isValid: true,
        isMobile: true,
        formattedNumber: `${cleanCode}${digits}`,
        displayNumber: `${cleanCode} ${digits.substring(0, 4)} ${digits.substring(4)}`,
      };
    }

    case '+1': { // US / Canada
      const isValidLength = digits.length === 10;
      const validFirstDigit = !['0', '1'].includes(digits.charAt(0));

      if (!isValidLength || !validFirstDigit) {
        return {
          isValid: false,
          isMobile: true,
          formattedNumber: `${cleanCode}${digits}`,
          displayNumber: `${cleanCode} ${digits}`,
          errorReason: 'US/Canada phone numbers require 10 valid digits (area code + 7 digits).',
        };
      }
      return {
        isValid: true,
        isMobile: true,
        formattedNumber: `${cleanCode}${digits}`,
        displayNumber: `${cleanCode} (${digits.substring(0, 3)}) ${digits.substring(3, 6)}-${digits.substring(6)}`,
      };
    }

    default: {
      const isValidLength = digits.length >= 7 && digits.length <= 14;
      if (!isValidLength) {
        return {
          isValid: false,
          isMobile: true,
          formattedNumber: `${cleanCode}${digits}`,
          displayNumber: `${cleanCode} ${digits}`,
          errorReason: `Please enter a valid phone number (7-14 digits). Entered ${digits.length} digits.`,
        };
      }
      return {
        isValid: true,
        isMobile: true,
        formattedNumber: `${cleanCode}${digits}`,
        displayNumber: `${cleanCode} ${digits}`,
      };
    }
  }
}

interface PhoneInputProps {
  id: string;
  value: string;
  onChange: (fullNumber: string) => void;
  inputClassName?: string;
  inputStyle?: React.CSSProperties;
  onFocus?: (e: any) => void;
  onBlur?: (e: any) => void;
  placeholder?: string;
  required?: boolean;
  theme?: 'dark' | 'light';
}

export default function PhoneInputWithCountry({
  id,
  value,
  onChange,
  inputClassName = 'invitation-input',
  inputStyle,
  onFocus,
  onBlur,
  placeholder,
  required = true,
  theme = 'dark',
}: PhoneInputProps) {
  const [countryCode, setCountryCode] = useState<string>('+61');
  const [localNumber, setLocalNumber] = useState<string>('');
  const [errorHint, setErrorHint] = useState<string>('');
  const [touched, setTouched] = useState<boolean>(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Auto-detect country code from IP on mount
  useEffect(() => {
    let isMounted = true;
    async function detectCountry() {
      try {
        const res = await fetch('https://ipapi.co/json/', { cache: 'no-store' });
        if (res.ok) {
          const data = await res.json();
          const callingCode = data.country_calling_code;
          if (callingCode && isMounted) {
            const formattedCode = callingCode.startsWith('+') ? callingCode : `+${callingCode}`;
            const match = COUNTRY_CODES.find((c) => c.code === formattedCode);
            if (match) {
              setCountryCode(match.code);
            } else if (formattedCode) {
              setCountryCode(formattedCode);
            }
          }
        }
      } catch {
        // Fallback to +61 (Australia for Roadshow)
      }
    }
    detectCountry();
    return () => {
      isMounted = false;
    };
  }, []);

  // Sync internal state if value is initialized externally with code
  useEffect(() => {
    if (!value) return;
    const match = COUNTRY_CODES.find((c) => value.startsWith(c.code));
    if (match) {
      setCountryCode(match.code);
      const numPart = value.replace(match.code, '').trim();
      setLocalNumber(numPart);
    }
  }, []);

  // Real-time validation handler
  const processValidation = (code: string, num: string, markTouched = false) => {
    if (!num.trim()) {
      setErrorHint(required && (touched || markTouched) ? 'Mobile phone number is required.' : '');
      if (inputRef.current) inputRef.current.setCustomValidity(required ? 'Mobile phone number is required.' : '');
      onChange('');
      return;
    }

    const validation = validatePhone(code, num);
    if (!validation.isValid) {
      const errorMsg = validation.errorReason || 'Please enter a valid mobile number.';
      setErrorHint((touched || markTouched) ? errorMsg : '');
      if (inputRef.current) inputRef.current.setCustomValidity(errorMsg);
      onChange(validation.formattedNumber);
    } else {
      setErrorHint('');
      if (inputRef.current) inputRef.current.setCustomValidity('');
      onChange(validation.formattedNumber);
    }
  };

  const handleCodeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newCode = e.target.value;
    setCountryCode(newCode);
    processValidation(newCode, localNumber, true);
  };

  const handleNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawVal = e.target.value;
    setLocalNumber(rawVal);
    setTouched(true);
    processValidation(countryCode, rawVal, true);
  };

  const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
    setTouched(true);
    processValidation(countryCode, localNumber, true);
    if (onBlur) onBlur(e);
  };

  const currentCountry = COUNTRY_CODES.find((c) => c.code === countryCode);
  const currentPlaceholder = placeholder || currentCountry?.placeholder || '412 345 678';
  const isLight = theme === 'light';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', width: '100%', gap: '4px' }}>
      <div style={{ display: 'flex', gap: '8px', width: '100%', alignItems: 'stretch' }}>
        <div style={{ position: 'relative', display: 'inline-flex', alignItems: 'center', flexShrink: 0 }}>
          <select
            value={countryCode}
            onChange={handleCodeChange}
            className={inputClassName}
            style={{
              appearance: 'none',
              WebkitAppearance: 'none',
              MozAppearance: 'none',
              width: 'auto',
              minWidth: '120px',
              padding: '0 32px 0 14px',
              fontSize: inputStyle?.fontSize || '14px',
              fontFamily: inputStyle?.fontFamily || "'Uxum Grotesque Medium', sans-serif",
              color: isLight ? '#010314' : (inputStyle?.color || '#e0c996'),
              backgroundColor: isLight ? 'rgba(1, 3, 20, 0.05)' : (inputStyle?.backgroundColor || '#02042d'),
              border: isLight ? '1px solid rgba(1, 3, 20, 0.2)' : (inputStyle?.border || '1px solid rgba(224, 201, 150, 0.35)'),
              cursor: 'pointer',
              borderRadius: 0,
              boxSizing: 'border-box',
              height: '100%',
            }}
            onFocus={onFocus}
          >
            {COUNTRY_CODES.map((item) => (
              <option
                key={item.code}
                value={item.code}
                style={{ backgroundColor: '#02042d', color: '#e0c996', padding: '8px' }}
              >
                {item.flag} {item.code}
              </option>
            ))}
          </select>

          {/* Custom Chevron Arrow */}
          <div style={{ position: 'absolute', right: '12px', pointerEvents: 'none', display: 'flex', alignItems: 'center', color: isLight ? '#010314' : '#e0c996' }}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="6 9 12 15 18 9"></polyline>
            </svg>
          </div>
        </div>

        <input
          ref={inputRef}
          id={id}
          name="phone"
          type="tel"
          required={required}
          value={localNumber}
          onChange={handleNumberChange}
          placeholder={currentPlaceholder}
          className={inputClassName}
          dir="ltr"
          style={{
            flex: 1,
            boxSizing: 'border-box',
            fontSize: '14px',
            borderColor: errorHint ? '#e74c3c' : undefined,
            ...inputStyle,
          }}
          onFocus={onFocus}
          onBlur={handleBlur}
        />
      </div>

      {/* Real-time Inline Error Hint */}
      {errorHint && (
        <span
          style={{
            fontFamily: "'Neue Montreal Regular', sans-serif",
            fontSize: '11px',
            color: '#e74c3c',
            marginTop: '2px',
            lineHeight: 1.3,
            display: 'block',
          }}
        >
          {errorHint}
        </span>
      )}
    </div>
  );
}
