// Centralized Conversion & Ad Attribution Tracking Module for WeNest
// Supports Google Ads (GTAG), Meta Ads (Facebook Pixel), GA4, and HubSpot CRM

export interface UtmParams {
  utm_source?: string;
  utm_medium?: string;
  utm_campaign?: string;
  utm_content?: string;
  utm_term?: string;
  gclid?: string;
  fbclid?: string;
}

export interface EventConversionData {
  eventName: string;
  eventLocation?: string;
  formType: 'roadshow_landing' | 'roadshow_popup' | 'event_rsvp';
  userEmail?: string;
  userPhone?: string;
  userName?: string;
  customGoogleAdsLabel?: string;
  eventId?: string;
}

export interface GenericLeadData {
  formName: string;
  projectName?: string;
  userEmail?: string;
  userPhone?: string;
  userName?: string;
  customGoogleAdsLabel?: string;
  eventId?: string;
}

const STORAGE_KEY = 'wenest_ad_attribution';
const GOOGLE_ADS_ID = process.env.NEXT_PUBLIC_GOOGLE_ADS_ID || 'AW-18364005209';
const DEFAULT_GOOGLE_ADS_EVENT_LABEL = process.env.NEXT_PUBLIC_GOOGLE_ADS_EVENT_LABEL || `${GOOGLE_ADS_ID}/IUx0COjQh98cEN6ok4FE`;

/**
 * Detects whether a lead submission is a test/demo contact.
 * Filters out inputs containing test emails, test names, or dummy phone numbers.
 */
export function isDemoContact(data: { email?: string; firstName?: string; lastName?: string; phone?: string; name?: string }): boolean {
  const email = (data.email || '').toLowerCase().trim();
  const fullName = `${data.firstName || ''} ${data.lastName || ''} ${data.name || ''}`.toLowerCase().trim();
  const phone = (data.phone || '').replace(/\D/g, '');

  const demoKeywords = ['test', 'demo', 'dummy', 'fake', 'sample', 'asdf', 'qwerty', 'testing', 'check', 'mailinator', 'yopmail', 'example'];

  // 1. Check if email contains any demo/test keyword (e.g. user@demo.com, test@gmail.com, demo123@...)
  if (demoKeywords.some((kw) => email.includes(kw))) return true;

  // 2. Check if full name contains any demo/test keyword
  if (demoKeywords.some((kw) => fullName.includes(kw))) return true;

  // 3. Check dummy phone numbers
  if (
    /^(\d)\1{5,}$/.test(phone) ||
    phone === '1234567890' ||
    phone === '123456789' ||
    phone === '0123456789' ||
    (phone.length > 0 && phone.length < 7)
  )
    return true;

  return false;
}

/**
 * Initializes Ad Click & UTM Attribution capture.
 * Stores query params (utm_*, gclid, fbclid) in sessionStorage & localStorage
 * so they persist across navigation until form submission.
 */
export function initAdTracking(): UtmParams {
  if (typeof window === 'undefined') return {};

  try {
    const searchParams = new URLSearchParams(window.location.search);
    const keys = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term', 'gclid', 'fbclid'];
    let freshDataFound = false;
    const captured: UtmParams = {};

    keys.forEach((key) => {
      const val = searchParams.get(key);
      if (val) {
        captured[key as keyof UtmParams] = val;
        freshDataFound = true;
      }
    });

    if (freshDataFound) {
      const existing = getStoredUtmParams();
      const merged = { ...existing, ...captured };
      window.sessionStorage.setItem(STORAGE_KEY, JSON.stringify(merged));
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(merged));
      return merged;
    }
  } catch (err) {
    console.error('Error reading/saving URL tracking params:', err);
  }

  return getStoredUtmParams();
}

/**
 * Retrieves stored ad tracking parameters.
 */
export function getStoredUtmParams(): UtmParams {
  if (typeof window === 'undefined') return {};

  try {
    const sessionData = window.sessionStorage.getItem(STORAGE_KEY);
    if (sessionData) return JSON.parse(sessionData);

    const localData = window.localStorage.getItem(STORAGE_KEY);
    if (localData) return JSON.parse(localData);
  } catch {
    /* ignore storage read errors */
  }

  return {};
}

/**
 * Helper to retrieve HubSpot tracking cookie (`hubspotutk`)
 */
export function getHubspotCookie(): string | undefined {
  if (typeof document === 'undefined') return undefined;
  const match = document.cookie.match(/(?:^|; )hubspotutk=([^;]*)/);
  return match ? decodeURIComponent(match[1]) : undefined;
}

/**
 * Safe wrapper for firing Google Tag / GA4 / Google Ads events.
 * Pushes directly to dataLayer using standard gtag arguments syntax if window.gtag is not yet initialized.
 */
export function fireGtagEvent(eventName: string, params: Record<string, unknown>) {
  if (typeof window === 'undefined') return;

  const w = window as any;
  w.dataLayer = w.dataLayer || [];

  if (typeof w.gtag !== 'function') {
    w.gtag = function () {
      w.dataLayer.push(arguments);
    };
  }

  w.gtag('event', eventName, params);
}

/**
 * Generates a unique event identifier for Meta Pixel & Meta CAPI deduplication.
 */
export function generateEventId(): string {
  return `evt_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
}

/**
 * Track Event Form Conversion across Meta Ads, Google Ads, GA4 & return enriched payload details.
 * DISTINCT FROM STANDARD INQUIRIES:
 * - Meta Pixel: 'CompleteRegistration' + custom 'EventFormSubmission' (with eventID deduplication)
 * - Google Ads: Dedicated Conversion Action + GA4 'event_registration_submit' + Enhanced Conversions user_data
 */
export function trackEventConversion(data: EventConversionData): string {
  if (typeof window === 'undefined') return '';

  const eventId = data.eventId || generateEventId();
  const utm = getStoredUtmParams();
  const eventDetails = {
    content_name: data.eventName,
    content_category: 'Event Registration',
    event_location: data.eventLocation || 'Melbourne',
    form_type: data.formType,
    currency: 'USD',
    value: 0,
    status: true,
    ...utm,
  };

  // Google Ads Enhanced Conversions User Data Object
  const userDataPayload = {
    email: data.userEmail ? data.userEmail.trim().toLowerCase() : undefined,
    phone_number: data.userPhone ? data.userPhone.replace(/\D/g, '') : undefined,
  };

  // 1. Meta Pixel Tracking (CompleteRegistration & Custom Event with eventID for CAPI deduplication)
  if (typeof (window as unknown as { fbq?: Function }).fbq === 'function') {
    const fbq = (window as unknown as { fbq: Function }).fbq;
    // Standard event: CompleteRegistration (allows Meta Ads to optimize specifically for event RSVPs)
    fbq('track', 'CompleteRegistration', eventDetails, { eventID: eventId });
    // Custom event: EventFormSubmission
    fbq('trackCustom', 'EventFormSubmission', {
      event_name: data.eventName,
      location: data.eventLocation,
      form_type: data.formType,
      ...utm,
    }, { eventID: eventId });
  }

  // 2. Google Ads & GA4 Tracking
  const conversionSendTo = data.customGoogleAdsLabel || DEFAULT_GOOGLE_ADS_EVENT_LABEL;

  // GA4 Custom Event for Event Submissions
  fireGtagEvent('event_registration_submit', {
    event_category: 'Event Conversion',
    event_label: data.eventName,
    ...eventDetails,
  });

  // Google Ads Specific Conversion Action Trigger (With Enhanced Conversions user_data)
  fireGtagEvent('conversion', {
    send_to: conversionSendTo,
    user_data: userDataPayload,
  });

  // Log in non-production for verification
  if (process.env.NODE_ENV !== 'production') {
    console.log('[Tracking] Event Conversion Fired:', data, 'EventId:', eventId, 'SendTo:', conversionSendTo);
  }

  return eventId;
}

/**
 * Track Standard Lead Conversion (for general contact & project brochure requests).
 * Keeps generic inquiries separate from event registrations.
 */
export function trackGenericLeadConversion(data: GenericLeadData): string {
  if (typeof window === 'undefined') return '';

  const eventId = data.eventId || generateEventId();
  const utm = getStoredUtmParams();
  const leadDetails = {
    content_name: data.formName,
    content_category: data.projectName || 'General Inquiry',
    currency: 'USD',
    value: 0,
    ...utm,
  };

  const userDataPayload = {
    email: data.userEmail ? data.userEmail.trim().toLowerCase() : undefined,
    phone_number: data.userPhone ? data.userPhone.replace(/\D/g, '') : undefined,
  };

  // 1. Meta Pixel: Standard Lead (with eventID for Meta CAPI deduplication)
  if (typeof (window as unknown as { fbq?: Function }).fbq === 'function') {
    const fbq = (window as unknown as { fbq: Function }).fbq;
    fbq('track', 'Lead', leadDetails, { eventID: eventId });
  }

  // 2. Google Ads & GA4: generate_lead & Google Ads conversion with Enhanced Conversions
  fireGtagEvent('generate_lead', leadDetails);

  const googleAdsLabel = data.customGoogleAdsLabel || process.env.NEXT_PUBLIC_GOOGLE_ADS_LEAD_LABEL || 'AW-18364005209/LYVeCM6gpMIcEN6ok4FE';
  fireGtagEvent('conversion', {
    send_to: googleAdsLabel,
    user_data: userDataPayload,
  });

  if (process.env.NODE_ENV !== 'production') {
    console.log('[Tracking] Generic Lead Conversion Fired:', data, 'EventId:', eventId);
  }

  return eventId;
}
