// Helper to format currency values in stats
const formatStatValue = (val: string, formatPrice: (amount: number) => string) => {
  const aedRegex = /AED\s*([\d,]+)/i;
  const match = val.match(aedRegex);
  if (match) {
    const num = parseInt(match[1].replace(/,/g, ''), 10);
    const formatted = formatPrice(num);
    return val.replace(aedRegex, formatted);
  }
  return val;
};

